from pathlib import Path
import json, hashlib
p=Path('studio/briefings.json'); data=json.loads(p.read_text()); before=json.dumps([{k:v for k,v in r.items() if k!='pointDetails'} for r in data],sort_keys=True)
def d(definition,mechanism,example,teachingCue): return dict(definition=definition,mechanism=mechanism,example=example,teachingCue=teachingCue)
D={}
D[1]=[
d('Coesão é quanto as responsabilidades de uma unidade contribuem para um propósito relacionado. Acoplamento é a dependência entre unidades: tipos conhecidos, chamadas necessárias e condições exigidas para continuar. Uma classe pode ter vários métodos coesos; desacoplar não significa eliminar toda dependência.', 'Observe o pedido de mudança e o trecho que precisa ser editado. Criar Email dentro da matrícula faz a regra conhecer uma escolha técnica. Esperar o envio antes de registrar acesso cria também uma dependência de execução.', 'MatriculasAcopladas declara Email e faz new Email(emailDisponivel). Para trocar o canal, essa classe muda. Em Matriculas, a escolha fica no main, enquanto os detalhes de envio ficam em Email ou WhatsApp.', 'Pergunte: “A regra de pagamento mudou? Então por que preciso editar a matrícula?” Aponte tipo, criação e ordem, não apenas caixas com nomes.'),
d('SRP — Princípio da Responsabilidade Única: separar razões independentes de mudança; critério de acesso e detalhe do aviso respondem a pedidos diferentes.\nOCP — Princípio Aberto/Fechado: permitir uma extensão identificada preservando a parte estável; novo canal pode preservar Matriculas.\nLSP — Princípio da Substituição de Liskov: substituir uma implementação mantendo promessas de comportamento; sucesso sem tentar enviar quebra a expectativa.\nISP — Princípio da Segregação de Interfaces: não obrigar consumidores a depender de operações desnecessárias; matrícula consulta pagamento, sem estorno ou nota.\nDIP — Princípio da Inversão de Dependência: política e detalhes dependem de abstrações; o contrato deve expressar a necessidade da política, sem particularidades do fornecedor.', 'DIP aparece nos tipos Notificador e ConsultaPagamento conhecidos por Matriculas e implementados pelos detalhes. DI — Injeção de Dependência — é entregar colaboradores de fora pelo construtor. Receber Email concreto já seria DI, mas manteria a dependência dessa implementação.', 'No main: Notificador notificador = new WhatsApp(); depois new Matriculas(new PagamentoLocal(), notificador). Novo canal: OCP. Promessa de enviar ou sinalizar IOException prevista: LSP. ConsultaPagamento pequeno: ISP. Regra e envio separados: SRP. Contratos na política: DIP.', 'Explique os nomes por extenso. Pergunte quem pede cada mudança, que contrato protege a regra e o que pode falhar legitimamente. Interface não garante comportamento nem resiliência.'),
d('Um main independente estabelece a montagem e a entrada de um único experimento. Isso permite comparar poucas linhas mantendo claro qual variável mudou; um menu com vários cenários esconderia o fluxo que a professora precisa apontar.', 'Leia cada demo de cima para baixo: criar colaboradores, construir Matriculas, criar pedidos, chamar confirmar e observar os conjuntos de acessos e pendências. Rode pelo executar.sh da aula, que compila antes de executar.', 'DemoEmail estabelece 3/3 com envio disponível. DemoAcoplamento falha antes do acesso; DemoDesacoplamento mantém acesso com aviso pendente. DemoWhatsApp troca o canal. DemoPagamentoPendente muda a condição do negócio e resulta em 0/3.', 'Deixe as cinco abas prontas. Antes de cada execução, peça uma previsão e nomeie a variável alterada: disponibilidade, canal ou status do pagamento.'),
d('Tolerância à falha depende do fluxo e do tratamento adotados. Um pagamento confirmado e um aviso indisponível podem produzir resultados diferentes conforme a ordem dos efeitos e o local onde a exceção é capturada.', 'MatriculasAcopladas chama email.enviar antes de acessos.add: IOException sai do método e impede a inclusão. Matriculas inclui o acesso primeiro, tenta enviar dentro de try e captura IOException, registrando a aluna em avisosPendentes.', 'Com Ana, Bia e Clara confirmadas e Email(false), a primeira versão fica em 0/3; a segunda, 3/3 com três pendências. Os números vêm dos Sets, não de um resultado fixo colocado no terminal.', 'Aponte a linha interrompida e a linha já realizada. Reforce que também seria possível tratar corretamente a falha na versão acoplada; uma interface sozinha não explica a continuidade.'),
d('Substituir um colaborador por contrato permite variar um detalhe mantendo o consumidor válido. A abstração precisa corresponder à operação e à semântica que o consumidor espera; ter a mesma assinatura Java não é suficiente.', 'O main escolhe a implementação e a entrega ao construtor. Matriculas conhece Notificador.enviar, sem referenciar Email ou WhatsApp. O mesmo fluxo consulta pagamento, registra acesso e tenta avisar, independentemente da escolha concreta.', 'Em DemoDesacoplamento, trocar Notificador notificador = new Email(false) por new WhatsApp() mantém o restante da montagem. O resultado esperado passa a 3/3 acessos e zero pendências, com mensagens locais de WhatsApp.', 'Mude uma linha e execute novamente. Mostre que a regra não foi editada; explique que essas implementações simulam envio no terminal, sem rede ou mensagens reais.')]
D[2]=[
d('Design pattern é uma solução recorrente de design em um contexto, com consequências e custos. Factory organiza criação; Singleton controla o acesso à mesma instância; Strategy separa algoritmos intercambiáveis; Adapter compatibiliza interfaces. Eles podem colaborar sem que um obrigue o uso dos outros.', 'Parta da mudança necessária: outro fornecedor, outra política de preço ou outro formato de integração. Localize a decisão no código antes de nomear o padrão. Contratos e objetos extras têm custo; uma condição simples pode continuar adequada.', 'A escola vende um curso de 10_000 centavos. DescontoPix calcula 9_000; PagamentoFactory fornece o colaborador; Adapter converte para reais; RegistroCompras conta compras confirmadas nesta execução.', 'Apresente preço, unidade e fornecedor simulado antes dos nomes de classes. Pergunte qual problema cada peça resolve e qual complexidade acrescenta.'),
d('Dependency Injection, ou Injeção de Dependência, é fornecer colaboradores de fora em vez de o consumidor escolher ou criar internamente. Strategy organiza alternativas de comportamento. A injeção entrega a estratégia; ela não define o algoritmo nem implica automaticamente inversão de dependência.', 'DemoCompra cria DescontoPix, obtém Pagamento pela Factory e RegistroCompras pelo getter. Esses três objetos entram no construtor de Checkout, que os guarda nos campos. Comprar usa politicaPreco.calcular e pagamento.cobrar, sem buscar a Factory durante a compra.', 'DemoSemDesconto troca a política para SemDesconto: a mesma entrada 10_000 passa a produzir 10_000, mantendo o fornecedor legado. Checkout continua usando o contrato PoliticaPreco.', 'Leia a montagem e depois o método comprar. Diferencie “quem fornece o objeto” de “quem calcula”. Receber RegistroCompras concreto ainda acopla ao tipo desse registro.'),
d('Simple Factory centraliza seleção e construção em um método que retorna um produto. Factory Method, no padrão clássico descrito por Gamma, Helm, Johnson e Vlissides, oferece um ponto de criação especializado por subclasses. Abstract Factory cria famílias relacionadas; esses dois últimos não são implementados aqui.', 'PagamentoFactory.criar usa switch sobre Fornecedor. O ponto central conhece os construtores concretos e entrega um Pagamento. O new não desapareceu: foi concentrado para o consumidor receber o colaborador pronto.', 'LEGADO retorna new PagamentoLegadoAdapter(new SdkLegado()); LOCAL retorna new PagamentoLocal(). Acrescentar uma opção neste switch exige alterar a Factory, embora Checkout possa continuar preservado.', 'Abra a Factory por dentro e aponte os dois new. Não classifique qualquer método estático de criação como Factory Method nem prometa criação extensível sem alterações.'),
d('Adapter oferece a interface esperada pelo cliente traduzindo para uma interface existente diferente. A tradução deve preservar significado: centavos inteiros e reais como texto representam a mesma quantia com unidades e tipos distintos.', 'PagamentoLegadoAdapter.cobrar transforma valorCentavos com BigDecimal.valueOf(valorCentavos, 2).toPlainString(), chama sdk.charge(valorReais, "BRL") e converte o retorno com movePointRight(2).intValueExact(). Checkout não conhece o formato do SDK.', 'Em DemoSemAdapter, Integer.toString(9000) produz "9000", interpretado como R$ 9.000. Com Adapter, 9000 produz "90.00": R$ 90, confirmado de volta como 9000 centavos.', 'Peça previsão para as mesmas entradas antes de executar. A conversão correta resolve a unidade; o Adapter organiza onde a tradução mora. Tudo é simulado localmente.'),
d('Singleton faz a própria classe controlar a construção e fornecer acesso à mesma instância naquele contexto de execução. Identidade compartilhada significa duas referências para um objeto; não significa duas cópias que sincronizam seus valores.', 'RegistroCompras tem construtor privado, campo static final INSTANCIA e getInstance retornando esse campo. Registrar incrementa quantidade. A inicialização de classe é coordenada pela JVM, mas quantidade++ não se torna uma operação concorrente segura por isso.', 'DemoSingleton fornece o mesmo registro a dois checkouts. registroAna == registroBia resulta true; após as duas compras, ambos leem 2. Novo comando Java inicia outra JVM e outro contador.', 'Desenhe um objeto e duas referências, depois 0 → 1 → 2. Ressalte perda no reinício, ausência de unicidade entre processos e possibilidade de compartilhar uma classe comum por injeção.')]
D[3]=[
d('Clean Architecture separa políticas de negócio de mecanismos externos. Entidades representam conceitos e comportamento do domínio; casos de uso coordenam intenções da aplicação; adaptadores traduzem formatos; frameworks e drivers ficam na borda. A regra de dependência orienta o conhecimento de tipos para dentro.', 'Pedido decide permiteMatricula. MatricularAluno coordena a decisão e chama RepositorioMatriculas. O caso de uso importa domínio e contrato de aplicação, sem Files, Path ou implementação concreta de armazenamento. RepositorioEmArquivo conhece o contrato interno e os mecanismos externos.', 'Trocar RepositorioEmMemoria por RepositorioEmArquivo muda o adaptador e a montagem, preservando a condição de pagamento. Apenas mover uma classe para uma pasta chamada dominio não alteraria seus imports.', 'Aponte dependência de código separadamente da chamada em execução. A chamada chega ao arquivo; o núcleo continua sem conhecer sua implementação.'),
d('Arquitetura Hexagonal, ou Ports and Adapters, separa núcleo e exterior por conversas explícitas. Porta de entrada descreve o que a aplicação oferece; porta de saída descreve o que ela precisa de um colaborador. Adaptadores traduzem tecnologias para essas conversas; não são as regras do negócio.', 'EntradaTerminal e EntradaCsv chamam Matricular.executar, implementado por MatricularAluno. Esse caso de uso chama RepositorioMatriculas para salvar. Memória e arquivo atendem à necessidade de saída, sem impor seu formato ao domínio.', 'O CSV transforma linha, campos e status em uma chamada da aplicação. O repositório de arquivo transforma salvar/listar em operações de filesystem. Ambos podem ser trocados independentemente.', 'Pergunte quem inicia cada conversa. Entrada e saída não significam dados só em um sentido: uma porta de saída também retorna resultados. Hexágono não exige seis portas.'),
d('O modelo arquitetural precisa ser compreendido antes dos nomes específicos do exemplo. Política descreve o que o negócio permite; mecanismo descreve como uma tecnologia realiza uma operação. Essa distinção permite reconhecer a mesma arquitetura em outra aplicação.', 'Apresente entidades, coordenação, tradução e tecnologias. Depois situe a escola: recebe nome e status de pagamento, registrando apenas confirmados. Associe os conceitos às classes somente quando atores, entrada, regra e resultado estiverem claros.', 'Pedido contém a elegibilidade; MatricularAluno coordena; Matricular e RepositorioMatriculas nomeiam conversas; terminal, CSV, memória e arquivo realizam traduções e mecanismos.', 'Abra com definição e objetivo. Relembre Ana e Clara confirmadas, Bia pendente. Não trate entidade como sinônimo obrigatório de tabela ou caso de uso como simples nome de pasta.'),
d('Persistência significa conservar dados além da vida do objeto ou processo que os produziu, segundo as garantias do armazenamento. Uma coleção de instância em memória e um arquivo externo têm vidas úteis diferentes; a interface de repositório não produz durabilidade por si mesma.', 'RepositorioEmMemoria mantém sua própria coleção. Outra instância cria outra coleção vazia. RepositorioEmArquivo escreve e lê o mesmo caminho externo, permitindo recuperar as linhas ao construir outro objeto que aponta para esse arquivo.', 'DemoCleanMemoria salva [Ana, Clara], mas a nova instância lista []. DemoCleanArquivo salva os mesmos nomes e a nova instância recupera [Ana, Clara]; Bia é rejeitada antes de salvar.', 'Abra o arquivo real e compare as montagens. Prepare a saída limpa para não acumular linhas de ensaios; esse arquivo didático não demonstra transação, concorrência ou banco de produção.'),
d('Um adaptador de entrada traduz dados e chama o caso de uso, sem implementar uma segunda regra de matrícula. Rejeição de negócio é diferente de erro de leitura: uma linha pode ter formato válido e ainda representar uma aluna inelegível.', 'EntradaCsv separa duas colunas por ponto e vírgula, converte o status para enum e chama Matricular.executar. MatricularAluno cria Pedido e retorna false quando permiteMatricula é falso, antes de chamar salvar. O mesmo caminho decide para terminal e CSV.', 'Ana e Clara entram no lote; Bia PENDENTE permanece recusada. Cada comando hex-terminal cria um processo e repositório em memória novos, portanto suas listas não acumulam entre invocações.', 'Reconstrua o caminho de Bia até o retorno antecipado. O leitor CSV é específico, sequencial e não atômico; não é um importador genérico com rollback de todo o lote.')]
D[4]=[
d('Monólito descreve implantação conjunta da aplicação como uma unidade. Modularidade descreve fronteiras lógicas por capacidades de negócio, com responsabilidades, contratos e dependências permitidas. Uma aplicação pode ter vários módulos, várias réplicas e banco externo mantendo um único deploy.', 'Financeiro concentra confirmação de pedidos; Acadêmico decide matrículas usando uma operação pública de Financeiro. Camadas técnicas como controller e repository podem existir dentro dos módulos, mas não são por si só capacidades de negócio.', 'DemoModulos cria Cobrancas, injeta em Matriculas, confirma apenas pedido-ana e solicita Ana e Bia. O resultado [Ana] vem da consulta ao contrato local; não existe serviço de rede.', 'Pergunte se separar pastas exige separar processos. Pastas sozinhas não impedem ciclos ou acesso indevido; a demo evidencia um limite específico, não proteção arquitetural completa.'),
d('Dono dos dados é o módulo responsável por manter suas invariantes e controlar alterações. Consumidores devem usar capacidades públicas em vez de conhecer ou modificar diretamente estruturas internas. Isso reduz dependência do layout, sem eliminar o acoplamento ao contrato escolhido.', 'Cobrancas guarda confirmadas em um Set privado e expõe estaConfirmado(pedido), retornando boolean. Acadêmico usa essa informação para decidir. Receber o conjunto mutável permitiria alterar confirmações sem passar pelas regras de Financeiro.', 'Matriculas não recebe acesso ao Set; sua listagem devolve cópia imutável. No SQL, financeiro_recebimentos e academico_matriculas documentam donos, mas os prefixos não criam permissões automaticamente.', 'Aponte o private e a resposta curta. Diferencie contrato concreto desta demo de isolamento completo por módulos, schemas ou credenciais de banco; esses mecanismos exigiriam configuração adicional.'),
d('Uma demonstração pode isolar mecanismos diferentes sem fingir que eles já estão integrados. A demo Java evidencia fronteiras e visibilidade; a demo SQLite evidencia uma transação executada pelo banco. O limite da linguagem não define o conceito arquitetural.', 'DemoModulos usa coleções em memória. transacao.py abre SQLite :memory: com autocommit explícito, carrega estrutura.sql e executa as duas escritas. Python fornece apenas o driver da biblioteca padrão, evitando baixar JDBC; o banco é real, mas efêmero.', 'Os modos modulos, sem-transacao e com-transacao do executar.sh são experimentos separados. A primeira execução não usa SQLite; cada execução SQL inicia um banco novo com a situação original de Ana.', 'Mostre apenas o trecho BEGIN, INSERTs e COMMIT/ROLLBACK. Não atribua ao Java uma garantia de banco que só foi demonstrada pelo segundo experimento.'),
d('Autocommit confirma cada instrução de forma independente. Uma transação explícita agrupa alterações numa unidade que confirma com COMMIT ou desfaz alterações ainda não confirmadas com ROLLBACK. Dois INSERTs no mesmo método não são automaticamente uma unidade atômica.', 'Ana já ocupa a vaga 1 antes do experimento. Inserir recebimento de Bia funciona; inserir sua matrícula na mesma vaga viola UNIQUE. Sem BEGIN, o recebimento já confirmou. Com BEGIN, a exceção leva ao rollback da tentativa de Bia.', 'Sem transação: recebimentos pedido-ana e pedido-bia, matrícula Ana. Com transação: recebimento pedido-ana e matrícula Ana. Os dados preexistentes de Ana permanecem; apenas a nova unidade é desfeita.', 'Mantenha entrada e falha iguais e pergunte qual escrita já estava confirmada. Explique atomicidade local; a demo não mede isolamento concorrente ou durabilidade em disco.'),
d('Rollback desfaz alterações participantes de uma transação local ainda não confirmada. Ele não reverte automaticamente efeitos feitos em outro banco ou numa API externa, porque esses participantes têm seus próprios limites de confirmação e protocolos.', 'Uma chamada HTTP ao provedor pode confirmar cobrança antes de a matrícula falhar no banco da escola. ROLLBACK na conexão SQLite não alcança o estado do provedor. Uma ação compensatória, como solicitar estorno, seria outra operação, com falhas e acompanhamento próprios.', 'O recebimento de Bia na demo é uma linha fictícia local. Sua remoção pelo rollback não comprova cancelamento de uma cobrança real; não houve comunicação com provedor.', 'Desenhe o limite do banco e o provedor fora dele. Pergunte quais efeitos participam do mesmo commit; use a distinção para preparar falhas parciais e compensação nas próximas aulas.')]
D[5]=[
d('Processo é uma execução com memória e recursos próprios. Servidor pode designar a máquina ou o processo que atende. Máquina virtual tem sistema operacional convidado; imagem é um pacote de inicialização; container é uma execução isolada. Localhost identifica o próprio contexto de rede de quem chama.', 'Servidor.java cria HttpServer em HOST e PORT. Uma requisição precisa alcançar esse endereço, uma porta escutada e o handler correto. HOST padrão 127.0.0.1 restringe a escuta local; 0.0.0.0 aceita interfaces do ambiente, não é um endereço de destino do cliente.', 'A aluna consultar 127.0.0.1:8080 procura um processo no ambiente dela, não o computador da professora. Docker Linux no Mac roda sobre ambiente Linux virtualizado.', 'Separe código, execução e ambiente no desenho. Pergunte onde o cliente está antes de interpretar localhost; não confunda container com uma máquina virtual completa.'),
d('Deploy disponibiliza e opera uma versão em um ambiente acessível aos usuários. Iniciar Java é uma etapa; acesso público, configuração, observação e continuidade operacional exigem decisões adicionais. Persistência é necessária para dados que precisam sobreviver ao processo, não uma propriedade automática de publicar.', 'Siga nome do serviço, resolução DNS, acesso por HTTPS e roteamento até a aplicação. Configure runtime, rede e valores de ambiente, observe logs e saúde, teste a versão e planeje retorno. O endpoint /health desta demo apenas responde; não verifica banco ou dependências.', 'A página /curso local responde nome da instância e visitas. Isso comprova HTTP no ambiente testado, sem demonstrar publicação na internet, armazenamento durável ou operação de um ambiente completo.', 'Pergunte onde a requisição pode parar. Relacione cada etapa a uma evidência observável, evitando tratar imagem criada ou handler saudável como deploy público concluído.'),
d('Estado local pertence à memória de uma execução. Reiniciar recria os objetos e pode perder esse estado. Duas execuções independentes não compartilham automaticamente seus contadores; selecionar manualmente uma porta não implementa balanceamento de carga.', 'Servidor.java instancia AtomicInteger com zero. Cada /curso executa incrementAndGet, portanto a primeira resposta mostra 1. Parar e iniciar o processo cria outro contador. INSTANCE identifica a resposta, enquanto PORT permite escutas separadas.', 'A na porta 8080 pode ter visitas 2 enquanto B em 8081 inicia em 1. Após restart de A, sua próxima visita volta a 1, mesmo se B continuar rodando.', 'Peça previsão antes do restart. A causa é a nova memória do processo, não cache do navegador; o cliente escolheu 8080 ou 8081 diretamente, sem um balanceador.'),
d('Imagem define o pacote; container executa esse pacote. EXPOSE documenta uma porta pretendida, mas não cria seu acesso no host. Publicar uma porta mapeia endereço e porta externos para a porta do processo dentro do ambiente do container.', 'No Dockerfile, HOST=0.0.0.0 e PORT=8080 permitem a escuta nas interfaces internas. O argumento -p 127.0.0.1:8081:8080 publica 8081 localmente e encaminha para 8080 interna. A publicação continua restrita ao computador pelo endereço 127.0.0.1.', 'curl http://127.0.0.1:8081/curso chega à aplicação do container na porta 8080 quando o container está rodando e a publicação foi configurada.', 'Aponte os dois números e o caminho. No Mac, containers Linux compartilham kernel do ambiente Linux usado pelo Docker Desktop, não diretamente o kernel Darwin do macOS.'),
d('Build produz um artefato; run cria uma execução a partir dele. Verificar uma dessas etapas não comprova a outra. Ensaiar significa executar os comandos reais e observar respostas no ambiente disponível, inclusive dependências de runtime e rede do primeiro build.', 'O Dockerfile usa estágio JDK 21 para javac e copia as classes para estágio JRE 21. ENTRYPOINT inicia Servidor; USER 10001:10001 evita executar como root. O runtime precisa estar disponível, a imagem base pode precisar de download e a porta publicada deve estar livre.', 'Pare B se ela ocupa 8081 antes do docker run. Faça curl em outro terminal, porque o terminal do container continua ocupado. O bloco HTTP direto permanece independente do Docker.', 'Confirme o estado do daemon e ensaie antes de gravar. Registre saída real; um teste local de container não constitui por si só serviço público disponível.')]
D[6]=[
d('Escalar é sustentar mais carga dentro dos objetivos de serviço. Escala vertical aumenta recursos de uma instância; horizontal distribui trabalho entre instâncias. O benefício depende de onde está o recurso saturado e de quanto do trabalho pode ser distribuído.', 'Observe volume de requisições, latência, erros e utilização dos recursos. Se réplicas web passam todas as consultas ao mesmo banco, multiplicá-las pode aumentar a pressão na origem. Uma técnica deve reduzir trabalho ou ampliar capacidade do gargalo identificado.', 'A demo de catálogo conta cinco consultas iguais na origem sem cache e uma com cache. Ela mede número de operações, sem medir duração nem provar ganho percentual de desempenho.', 'Pergunte “qual recurso está caro ou saturado?” antes de propor réplicas. Preserve objetivos e carga comparável; contador de acessos não equivale a benchmark de latência.'),
d('Cache reutiliza uma cópia e pode servir dado antigo. CDN, rede de distribuição de conteúdo, aproxima conteúdo dos clientes conforme regras de cache. Balanceamento distribui pedidos entre alvos. Rate limiting limita admissões por chave e intervalo. Cada técnica atua sobre uma pressão diferente.', 'Cache reduz consultas à origem; CDN pode reduzir viagens e tráfego de conteúdo público; balanceador distribui trabalho sem remover necessariamente o gargalo compartilhado; limitador reduz excesso aceito sem criar capacidade nova. Todos exigem política para estado, falha ou atualização.', 'A imagem pública do curso pode ir à CDN; sessão privada não deve virar cache público; a compra pode exigir preço atual na origem. CachePreco e LimitePorJanela modelam apenas dois desses mecanismos.', 'Peça técnica, recurso poupado e custo novo. Não apresente CDN ou balanceador como implantados: eles são conceituais nesta aula, enquanto o Java é local.'),
d('Cache guarda uma cópia reutilizável da origem. Miss significa ausência de cópia e exige consulta; hit reutiliza o valor existente. Alterar a origem não atualiza automaticamente a cópia, a menos que uma política de atualização ou invalidação cuide dessa mudança.', 'CachePreco consulta Catalogo somente quando seu valor ainda não foi preenchido. Catalogo incrementa o contador de consultas na própria operação. Invalidar remove a cópia e força a próxima leitura a buscar o valor da origem.', 'Cinco leituras geram cinco consultas sem cache e uma com cache. Origem passa de 10000 para 12000; cache ainda retorna 10000. Após invalidar, retorna 12000 e a contagem da origem chega a duas.', 'Mostre economia e desatualização como consequências do mesmo mecanismo. Não cite TTL implementado: aqui a política demonstrada é invalidação explícita, sem espera de tempo.'),
d('Stateless significa que uma réplica não depende do estado local de sessão criado por pedidos anteriores para atender ao próximo. O sistema ainda mantém estado, mas precisa de uma representação ou armazenamento acessível aos participantes apropriados. Afinidade de sessão é outra escolha, com dependência da réplica.', 'DemoEstadoLocal fornece um objeto Sessoes diferente a cada Replica. Login salva Ana em A, mas B consulta sua própria coleção vazia. DemoEstadoCompartilhado injeta a mesma instância de Sessoes em ambos os objetos, isolando a causa lógica.', 'No primeiro resultado, A encontra Ana e B fica SEM SESSÃO; no segundo, ambas encontram Ana. As réplicas são objetos na mesma JVM, sem processos remotos ou Redis.', 'Pergunte o que acontece quando o pedido seguinte chega a B. Em produção, armazenamento entre processos acrescenta latência, expiração, disponibilidade e segurança; compartilhar um objeto Java não implementa isso.'),
d('Rate limiting controla quantas operações uma chave pode admitir em um intervalo. Na janela fixa, todas as chaves compartilham fronteiras de tempo, mas mantêm contagens próprias. O limitador protege capacidade; não aumenta a capacidade e pode permitir rajadas perto da virada da janela.', 'LimitePorJanela calcula segundo / 60. Quando a janela muda, limpa as contagens. Para a chave cliente, permite enquanto usadas < limite e incrementa apenas a chamada aceita. O tempo chega como argumento, tornando a demo reproduzível.', 'Ana passa nas primeiras três chamadas; quarta e quinta são recusadas. Bia tem sua própria cota. Em t=60, Ana volta a passar. Duas instâncias do limitador manteriam duas cotas independentes.', 'Aponte chave, janela e contador. O método retorna boolean; o adaptador HTTP poderia traduzir recusa para 429. O mapa local sequencial não é um limite distribuído global.')]
D[7]=[
d('A decisão compara fronteiras de implantação e de negócio. Monólito implanta componentes juntos; microserviços permitem evolução e implantação independente por capacidades e contratos. Propriedade dos dados e autonomia das equipes precisam acompanhar essas fronteiras para que a independência tenha valor.', 'Separar processos introduz transporte, compatibilidade, observabilidade e falhas parciais. Se mudanças continuam coordenadas em todos os serviços ou consumidores escrevem diretamente nas tabelas alheias, parte do benefício de autonomia pode desaparecer.', 'Uma equipe pequena que muda matrícula e cobrança juntas pode escolher um monólito modular. Processamento de vídeos com escala e evolução próprias pode justificar separação. Réplicas do mesmo monólito não viram microserviços.', 'Peça uma necessidade concreta de implantação ou escala independente. Compare o benefício com o custo operacional, sem chamar uma arquitetura de estágio obrigatório de maturidade.'),
d('Falha parcial acontece quando uma etapa ou participante falha enquanto outro já executou sua parte. Cada banco tem um limite de transação local; confirmar ou desfazer ali não coordena automaticamente commits de outros bancos ou efeitos externos.', 'Uma cobrança pode confirmar no provedor e a resposta não chegar ao checkout. Uma matrícula posterior pode falhar no banco local sem desfazer a cobrança. O desenho precisa admitir estados intermediários, consulta de reconciliação e coordenação explícita conforme a regra de negócio.', 'O mesmo monólito que chama uma API externa pode sofrer essa falha. O risco vem da fronteira remota, não do nome microserviço. As demos isolam o efeito confirmado seguido de resposta perdida.', 'Desenhe cada fronteira de commit. Pergunte qual participante sabe o quê e que estado é aceitável para o negócio, antes de escolher a forma de distribuição.'),
d('Timeout informa que o cliente não recebeu uma confirmação dentro do prazo; não informa sozinho se o efeito aconteceu. UNKNOWN representa essa incerteza de conhecimento do cliente. É diferente de recusa explícita pelo provedor.', 'Provedor.cobrar registra o pedido na lista antes de lançar TimeoutException quando a resposta é perdida. O experimento conhece essa ordem, mas um cliente real só observa ausência de resposta. Ele deve consultar ou repetir com a identidade apropriada, conforme o contrato remoto.', 'DemoRetry mostra UNKNOWN na primeira chamada enquanto a coleção do provedor já contém uma cobrança. Repetir sem proteção aplica outra cobrança; capturar a exceção não desfaz a primeira.', 'Peça “timeout prova pagamento recusado?” e espere a resposta. A mensagem controlada da demo revela a causa didática; não é uma informação disponível por qualquer timeout real.'),
d('Idempotência permite repetir a mesma intenção sem reaplicar seu efeito. Uma chave estável identifica a operação, e seus parâmetros precisam continuar compatíveis. Uma chave nova pode representar uma nova intenção, mesmo se a pessoa e o produto parecerem iguais.', 'ProvedorIdempotente guarda chave e valor no Map. Se a chave existe com outro valor, rejeita o conflito. putIfAbsent evita nova entrada para a mesma chave; a tentativa pode perder a resposta depois do registro e ser consultada/repetida sem aumentar a quantidade.', 'DemoRetry termina com duas cobranças. DemoIdempotencia reutiliza pedido-ana e termina com uma: primeira resposta desconhecida, segunda confirmada. Manter a chave e trocar 10000 por 12000 gera conflito.', 'Compare identidade, efeito e resposta. A diferença vem do registro da operação; interfaces, try/catch ou o nome do padrão não tornam uma cobrança automaticamente idempotente.'),
d('Uma garantia durável precisa sobreviver a reinícios e coordenar participantes concorrentes. O mapa local da demo só demonstra o raciocínio em uma thread. Ele não conserva resultados entre processos nem protege sozinho a aplicação financeira distribuída.', 'Em uma implementação real, chave, parâmetros, efeito e resultado precisam de armazenamento e coordenação adequados, incluindo unicidade, atomicidade, retenção e recuperação. O cliente também deve preservar a identidade entre suas tentativas; para efeito externo, dependem as garantias do destino.', 'Reiniciar ProvedorIdempotente cria outro Map e perde o histórico. Várias réplicas com mapas próprios não reconhecem automaticamente a cobrança feita por outra. A demonstração não executa HTTP ou espera um timeout real.', 'Declare esse limite antes da execução e aponte o estado em memória. Diferencie “mostramos uma regra de deduplicação” de “implementamos idempotência financeira de produção”.')]
D[8]=[
d('Comando pede uma ação; evento informa um fato ocorrido. Uma fila permite que produtor e consumidor atuem em momentos diferentes, conforme garantias de armazenamento, entrega e confirmação. Isso muda a coordenação temporal, sem eliminar contratos ou garantir mais velocidade.', 'O produtor publica trabalho; o worker obtém uma mensagem, realiza um efeito e confirma. Se a chegada supera o processamento, acumula backlog. Consumidores concorrentes normalmente dividem o trabalho de uma fila; consumidores independentes de um fato exigem topologia de distribuição adequada.', 'EnviarAviso expressa intenção; MatriculaConfirmada expressa fato. Na história, Ana pode ter acesso enquanto seu aviso ainda espera processamento. Evento carrega ID para acompanhar a mesma ocorrência.', 'Pergunte se a mensagem pede algo ou anuncia algo concluído. Explique quem aceita o estado intermediário; apenas colocar consumidores na mesma fila não implica broadcast.'),
d('ACK é a confirmação do consumidor de que uma entrega pode ser encerrada segundo o contrato do broker. Redelivery é nova entrega quando falta essa confirmação. Retry repete após falha; DLQ, fila de mensagens não processadas, separa casos que excederam uma política para investigação e tratamento.', 'Confirmar antes do efeito pode perder trabalho; efeito antes do ACK pode repetir se a confirmação se perder. Use atraso e limite para falhas transitórias; dados inválidos não melhoram com repetição infinita. Saga coordena transações locais com compensações para efeitos já confirmados.', 'O roteiro ilustra três tentativas e depois DLQ. No cenário de Saga, reserva aceita e cobrança recusada levam a liberar reserva: uma nova ação que também pode falhar, não rollback global.', 'Distinga ACK de consumidor e confirmação produtor→broker. Pergunte qual etapa foi confirmada. Retry/DLQ/Saga são explicados conceitualmente, sem implementação completa nessas demos.'),
d('Transactional Outbox registra a mudança de negócio e a intenção de publicar na mesma transação local. Um relay, ou publicador, envia as pendências ao broker depois. Essa coordenação protege a intenção; não transforma publicação remota e commit local em uma única operação atômica.', 'Salvar matrícula e publicar separadamente abre uma janela de perda. Com outbox, falha antes do envio deixa pendência recuperável. Se o relay publicar e falhar antes de marcar envio, poderá publicar de novo; o consumidor precisa aceitar repetição corretamente.', 'DemoEventoPerdido salva Ana e deixa fila vazia. DemoOutbox cria Estado com matrícula e evento, depois publica. A demo não marca a pendência enviada: rodar o loop novamente publicaria o evento outra vez.', 'Siga commit local, pendência, publicação e marcação. O novo Estado em memória modela a gravação conjunta sequencial; não é uma tabela durável nem uma transação real de banco.'),
d('O efeito e a confirmação são etapas diferentes. Se um worker aplica o efeito e para antes de confirmar, a entrega pode voltar. Idempotência do consumidor usa uma identidade estável para reconhecer que aquele efeito já foi realizado, sem presumir entrega única pelo broker.', 'Fila.proximo usa peek e não remove; confirmar remove. DemoEntregaDuplicada registra duas vezes o mesmo evento ainda presente. Notificacoes.registrarUmaVez consulta processados antes de adicionar o aviso e depois registra seu ID. O efeito aqui é uma lista local, não envio de e-mail.', 'O evento-1 de Ana produz [Ana, Ana] sem deduplicação e [Ana] com deduplicação. Nos dois casos, a primeira tentativa ocorre antes do ACK; muda o tratamento da identidade no consumidor.', 'Pergunte quantos avisos haverá antes de rodar. Mostre onde o ID e o efeito ficam; o HashSet não torna a checagem e a gravação atômicas sob concorrência.'),
d('Recuperação durável exige persistência e coordenação das etapas relevantes. Uma fila em ArrayDeque e um conjunto em HashSet desaparecem quando o processo termina. Um modelo SQL pode descrever a garantia necessária sem comprovar que a aplicação já usa um broker, transações ou recuperação após crash.', 'contratos.sql descreve produtor gravando matrícula e outbox juntos, e consumidor gravando ID único e aviso juntos. ACK deve vir após commit local. Se o efeito for uma API externa, essa transação não cobre automaticamente a chamada; é preciso a garantia do destino ou outra coordenação.', 'As paradas Java omitem etapas controladamente sem matar a JVM. Saga usa outro cenário: reserva, cobrança recusada e compensação da reserva; não reverte o tempo nem o histórico da tentativa.', 'Declare memória e execução sequencial. Peça que o aluno localize o commit e a fronteira externa; não confunda o desenho da garantia com uma integração implementada.')]
for row in data:
 row['pointDetails']=D[row['lessonNumber']]
 assert len(row['pointDetails'])==len(row['points'])==5
 for index, detail in enumerate(row['pointDetails'],1):
  assert set(detail)=={'definition','mechanism','example','teachingCue'}
  assert all(isinstance(v,str) and v.strip() for v in detail.values())
  count=sum(len(v.split()) for v in detail.values())
  print(row['lessonNumber'],index,count)
assert json.dumps([{k:v for k,v in r.items() if k!='pointDetails'} for r in data],sort_keys=True)==before
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
